"""Cuaderno del estudiante, 8.º básico Lengua y Literatura, OA 25 (investigación sobre lenguaje y literatura).

Todas las fuentes, autores y datos de los ejercicios son ficticios y están escritos como ejemplo.
"""
from __future__ import annotations

from student_content_le8_c import E, L

OA25 = "LE08 OA 25"
MAT25 = "Este cuaderno, lápiz y las descripciones de fuentes ficticias escritas en cada ejercicio; si quieres practicar, puedes usar un libro o un artículo que tengas en casa."

L(OA25, 1,
  MAT25,
  "Aprenderé a delimitar un tema de investigación sobre lenguaje o literatura, transformándolo en una pregunta acotada que se pueda responder con fuentes.",
  ["Sé distinguir tema y pregunta.", "Conozco géneros literarios como cuento, poema y leyenda."],
  ["Investigar es buscar información para responder una pregunta. Muchas veces se parte de un tema muy amplio, como «la poesía» o «los refranes». Un tema amplio no se puede investigar bien porque hay demasiado que leer. Delimitar es acotar el tema con tres decisiones: qué aspecto (recursos, personajes, mensajes), qué tiempo o lugar (Chile, el siglo XX, mi región) y qué tipo de textos (poemas breves, leyendas, refranes de trabajo).",
   "Una buena pregunta de investigación es: 1) delimitada (tiene aspecto, lugar o tiempo); 2) investigable (se responde con fuentes, no con una opinión); 3) abierta (pide explicar, no solo «sí» o «no»); y 4) pertinente (tiene sentido en lenguaje y literatura). Por ejemplo: «¿Qué recursos usan los poemas breves sobre el mar?» es mejor que «¿La poesía es linda?».",
   "Después de formular la pregunta, define su alcance: qué incluirás y qué no. Por ejemplo, incluirás cinco poemas breves y no los poemas largos. El alcance te ayuda a saber cuándo has reunido suficiente información. Puedes ajustar la pregunta si descubres que es demasiado amplia o que no hay fuentes disponibles."],
  [("delimitar", "acotar un tema a un aspecto, tiempo, lugar o tipo de textos"), ("pregunta de investigación", "interrogante que se responde con fuentes"), ("alcance", "lo que se incluirá y lo que no en la investigación"), ("investigable", "que se puede responder con fuentes")],
  [("Delimitar un tema", "Tema: «los refranes». Delimita con aspecto y lugar.",
    ["El tema es amplio.", "Elijo un aspecto: consejos sobre el trabajo.", "Elijo un lugar: Chile. La pregunta: ¿Qué consejos sobre el trabajo dan los refranes usados en Chile?"],
    "¿Qué consejos sobre el trabajo dan los refranes usados en Chile?"),
   ("Evaluar una pregunta", "¿Es investigable «¿La poesía es linda?»?",
    ["Es una opinión.", "No se responde con fuentes.", "No es investigable."],
    "No: es una opinión")],
  [("Elegir una pregunta demasiado amplia.", "Se parte con el tema completo.", "Delimita aspecto, lugar o tiempo."),
   ("Formular una pregunta de sí o no.", "Se busca una respuesta rápida.", "Pregunta qué, cómo o por qué.")],
  ([E("¿«La poesía» es un tema amplio o delimitado?", "Amplio", "Falta aspecto, lugar o tipo de texto."),
    E("¿Una buena pregunta de investigación se responde solo con sí o no?", "No", "Debe pedir explicación."),
    E("¿Delimitar es acotar un tema?", "Sí", "Se reduce a un aspecto concreto.")],
   [E("¿Cuál es más delimitada: «La poesía» o «¿Qué recursos usan los poemas breves sobre el mar?»", "¿Qué recursos usan los poemas breves sobre el mar?", "Tiene aspecto y tipo de texto."),
    E("¿Cuál es investigable: «¿Qué personajes aparecen en las leyendas de una región?» o «¿Es bonita la poesía?»", "¿Qué personajes aparecen en las leyendas de una región?", "Se responde con fuentes."),
    E("¿Qué elemento delimita «de mi región» en «las leyendas de mi región»: lugar o tiempo?", "Lugar", "Indica dónde se ubican las leyendas.")],
   [E("Tema: «las adivinanzas». ¿Qué pregunta delimita mejor: «¿Qué son las adivinanzas?» o «¿Qué recursos usan las adivinanzas sobre animales para plantear un enigma?»", "¿Qué recursos usan las adivinanzas sobre animales para plantear un enigma?", "Tiene aspecto y tema acotado."),
    E("Tema: «las fábulas». Agrega aspecto: «¿Qué ___ enseñan las fábulas de animales?». Elige: moralejas / colores.", "Moralejas", "Es el mensaje de una fábula."),
    E("¿Cuál es un alcance razonable para una investigación escolar: cinco poemas breves o todos los poemas de la historia?", "Cinco poemas breves", "Se puede abarcar.")],
   [E("Una pregunta dice «¿Cómo es la literatura?». ¿Por qué es difícil de investigar?", "Porque es demasiado amplia", "No tiene aspecto ni delimitación."),
    E("Si no encuentras fuentes para tu pregunta, ¿qué conviene: ajustar la pregunta o rendirse?", "Ajustar la pregunta", "Se puede acotar o cambiar.")],
   [E("Evalúa «¿Por qué los refranes del trabajo usan comparaciones con animales en Chile?». ¿Es delimitada?", "Sí", "Tiene aspecto, lugar y tipo de texto."),
    E("Evalúa «¿Los cuentos son buenos?». ¿Cuál es el problema principal?", "Es una opinión sin delimitar", "No es investigable ni acotada.")]),
  [E("Una estudiante quiere investigar «el humor». Elige la mejor pregunta: «¿Qué recursos usan los cuentos breves de humor para hacer reír?» o «¿Es divertido el humor?»", "¿Qué recursos usan los cuentos breves de humor para hacer reír?", "Es delimitada e investigable.")],
  [E("¿Una pregunta investigable se responde con fuentes?", "Sí", "No con opiniones."),
   E("¿El alcance dice lo que se incluirá y lo que no?", "Sí", "Ayuda a saber cuándo basta."),
   E("¿Se puede ajustar la pregunta durante la investigación?", "Sí", "Si es muy amplia o no hay fuentes.")],
  ("Parte del tema de ejemplo «las leyendas». 1) Escribe tres decisiones de delimitación (aspecto, lugar y tipo o cantidad de textos). 2) Formula una pregunta de investigación delimitada, abierta e investigable. 3) Define su alcance en una frase (qué incluyes y qué no). 4) Explica por qué la pregunta es investigable.",
   "Decisiones: aspecto, los personajes; lugar, una región de Chile; cantidad, cuatro leyendas. Pregunta: «¿Qué rasgos comparten los personajes de cuatro leyendas de una región de Chile?». Alcance: incluyo cuatro leyendas escritas de la región y no leyendas de otros países. Es investigable porque se responde leyendo y comparando textos.",
   ["delimita aspecto, lugar y cantidad", "formula una pregunta abierta", "define alcance"], ["tres decisiones", "pregunta", "alcance y justificación"], ["pregunta de sí o no", "alcance sin límites"], "Lee tu pregunta a otra persona y pregúntale si entiende qué investigarás."),
  "Piensa en un tema que te interese de lenguaje o literatura y escríbelo como una pregunta delimitada.",
  "Formula tres preguntas de investigación sobre el mismo tema, cada una con un aspecto distinto.")

L(OA25, 2,
  MAT25,
  "Aprenderé a buscar información de manera eficiente usando palabras clave, organizadores (índice, títulos, glosario) y la estructura de los textos.",
  ["Delimito una pregunta de investigación.", "Reconozco partes de un libro o artículo."],
  ["Buscar información es más fácil con palabras clave: términos centrales de tu pregunta. Para «¿Qué recursos usan los poemas breves sobre el mar?», las palabras clave son «poemas breves», «mar» y «recursos». Si no hay resultados, prueba sinónimos («versos cortos») o términos más generales o más específicos. En buscadores, las comillas ayudan a buscar una expresión exacta.",
   "Los libros y textos tienen organizadores que te ahorran tiempo: el índice (lista de capítulos con páginas), los títulos y subtítulos, las negritas, el glosario (definiciones de términos), la introducción y la conclusión. Antes de leer todo, revisa estos organizadores para ubicar la parte que responde a tu pregunta.",
   "También sirve conocer la estructura del texto. En un artículo, el resumen o primer párrafo suele contener lo central; en cada párrafo, la oración inicial suele presentar la idea principal; en un texto expositivo, la conclusión resume los hallazgos. Con estas pistas puedes leer de manera selectiva: salta lo que no necesitas y lee con detalle lo pertinente. Anota dónde encontraste cada dato."],
  [("palabra clave", "término central de una pregunta usado para buscar información"), ("índice", "lista de capítulos o temas con la página en que están"), ("glosario", "lista de términos con sus definiciones"), ("lectura selectiva", "leer solo las partes que responden a la pregunta")],
  [("Elegir palabras clave", "Pregunta: «¿Qué moraleja enseñan las fábulas de animales?». ¿Cuáles son dos palabras clave?",
    ["Busco los términos centrales.", "«Moraleja» y «fábulas».", "«Animales» también ayuda."],
    "Moraleja y fábulas"),
   ("Usar el índice", "Índice de ejemplo: Capítulo 1, Qué es una fábula (p. 5); Capítulo 2, Animales protagonistas (p. 18); Capítulo 3, La moraleja (p. 31). ¿Dónde buscas sobre la moraleja?",
    ["Busco el capítulo cuyo título coincide.", "Es el capítulo 3.", "Está en la página 31."],
    "Capítulo 3, página 31")],
  [("Leer todo el libro sin ubicar lo que sirve.", "No se revisan los organizadores.", "Mira el índice y los títulos primero."),
   ("Buscar solo con la pregunta completa.", "Se escribe la frase entera.", "Usa palabras clave y sinónimos.")],
  ([E("Pregunta: «¿Qué moraleja enseñan las fábulas de animales?». ¿Es «moraleja» una palabra clave?", "Sí", "Es un término central."),
    E("¿El índice indica en qué página está cada capítulo?", "Sí", "Es su función."),
    E("¿Las comillas en un buscador ayudan a buscar una expresión exacta?", "Sí", "Buscan las palabras juntas.")],
   [E("Índice de ejemplo: Cap. 1, Qué es una leyenda (p. 4); Cap. 2, Personajes de las leyendas (p. 15); Cap. 3, Lugares de las leyendas (p. 27). ¿En qué página buscas sobre los personajes?", "En la página 15", "El capítulo 2 trata de ellos."),
    E("Si no encuentras resultados con «poemas breves», ¿qué sinónimo puedes probar: «versos cortos» o «novelas largas»?", "Versos cortos", "Es un término cercano."),
    E("¿Qué organizador define términos: el glosario o el índice?", "El glosario", "Es la lista de definiciones.")],
   [E("Pregunta: «¿Qué recursos usan los poemas breves sobre el mar?». ¿Cuál es el mejor conjunto de palabras clave: poemas breves, mar, recursos o libro, página, autor?", "Poemas breves, mar, recursos", "Son los términos centrales."),
    E("Para ubicar una definición, ¿dónde buscas: en el glosario o en la portada?", "En el glosario", "Reúne todas las definiciones."),
    E("Un artículo tiene resumen, introducción, desarrollo y conclusión. Si quieres lo central rápido, ¿qué lees primero: el resumen o los agradecimientos?", "El resumen", "Presenta lo central.")],
   [E("¿Por qué la lectura selectiva ahorra tiempo?", "Porque solo se lee lo que responde a la pregunta", "Evita leer partes que no sirven."),
    E("Si una primera oración de párrafo dice «Este párrafo habla de recetas», ¿es útil para una pregunta sobre poemas?", "No", "Se aleja de la pregunta.")],
   [E("Estás buscando en un buscador la frase exacta «versos cortos sobre el mar». ¿Qué signo la mantiene unida?", "Las comillas", "Buscan las palabras juntas."),
    E("Un libro de ejemplo tiene 120 páginas y el índice muestra que la moraleja está en el capítulo 3 (p. 31). ¿Es eficiente leer desde la página 1?", "No", "Conviene ir directo al capítulo pertinente.")]),
  [E("Quieres saber el significado de «moraleja» en un libro de ejemplo. El libro tiene índice, glosario y portada. ¿Qué parte consultas primero?", "El glosario", "Define los términos nuevos.")],
  [E("¿Las palabras clave son términos centrales de la pregunta?", "Sí", "Orientan la búsqueda."),
   E("¿El índice ahorra tiempo para ubicar partes de un libro?", "Sí", "Indica las páginas exactas."),
   E("¿Se pueden probar sinónimos si no hay resultados?", "Sí", "Amplían la búsqueda.")],
  ("Pregunta de ejemplo: «¿Qué recursos usan los cuentos breves de misterio para crear suspenso?». Fuente de ejemplo (libro ficticio): Índice: Cap. 1, Qué es un cuento (p. 3); Cap. 2, El suspenso (p. 20); Cap. 3, Personajes (p. 40); Cap. 4, Glosario (p. 80). 1) Escribe cuatro palabras clave y dos sinónimos o términos alternativos. 2) Indica qué capítulos leerías y cuáles no. 3) Escribe cómo buscarías la expresión exacta «cuentos de misterio» en un buscador.",
   "Palabras clave: cuentos breves, misterio, suspenso, recursos. Alternativos: relatos cortos, intriga. Leería el capítulo 2 (suspenso) y el glosario si hay términos nuevos; dejaría de lado el capítulo 3 salvo que necesite personajes. Buscador: \"cuentos de misterio\" entre comillas.",
   ["elige palabras clave", "usa el índice para decidir qué leer", "emplea comillas para una búsqueda exacta"], ["palabras clave", "plan de lectura", "búsqueda escrita"], ["leer todo", "usar la pregunta completa como búsqueda"], "Comparte tu plan con otra persona y pregúntale si agregaría otra palabra clave."),
  "Elige un libro de tu casa y busca en su índice la parte que serviría para una pregunta de tu interés.",
  "Escribe diez palabras clave para tres preguntas distintas.")

L(OA25, 3,
  MAT25,
  "Aprenderé a evaluar si las fuentes son confiables y si entregan suficiente información para responder mi pregunta o cumplir mi propósito.",
  ["Busco con palabras clave.", "Distingo hechos y opiniones."],
  ["Una fuente es confiable si cumple varios criterios: tiene autor o institución identificable, indica la fecha, cita sus datos, es coherente con otras fuentes y no busca solo vender o persuadir. Una fuente que exagera, no cita datos o copia sin autoría merece cautela. Evaluar la confiabilidad es el primer filtro de una investigación.",
   "Pero una fuente confiable puede no ser suficiente. La suficiencia se refiere a si la información alcanza para responder la pregunta o cumplir el propósito. Si tu pregunta es «¿Qué recursos usan los poemas breves sobre el mar?» y una fuente solo dice que los poemas son «bonitos», no es suficiente: no menciona recursos ni ejemplos. Para ser suficiente, una fuente debe tratar el aspecto de tu pregunta con datos o ejemplos.",
   "Una buena práctica es construir una tabla con las fuentes y marcar cada criterio: autor, fecha, datos citados, coherencia, relación con la pregunta. Si ninguna fuente alcanza, busca más. Si dos fuentes se contradicen, compáralas y decide con criterios. Anota también las limitaciones: «Las fuentes encontradas cubren solo poemas del siglo XX»."],
  [("confiable", "que merece confianza por su autoría, respaldo y coherencia"), ("suficiente", "que alcanza para responder la pregunta"), ("criterio", "aspecto con que se juzga una fuente"), ("limitación", "aspecto que la investigación no logra cubrir")],
  [("Evaluar confiabilidad", "Fuente ficticia: artículo de una revista de literatura con autora identificada, fecha 2021 y ejemplos citados. ¿Es confiable?",
    ["Tiene autoría.", "Tiene fecha y ejemplos citados.", "Cumple los criterios."],
    "Sí, cumple los criterios"),
   ("Evaluar suficiencia", "Pregunta: ¿Qué recursos usan los poemas breves sobre el mar? Fuente: «Los poemas sobre el mar son bonitos». ¿Es suficiente?",
    ["La fuente no menciona recursos.", "No ofrece ejemplos.", "No es suficiente."],
    "No es suficiente: no habla de recursos")],
  [("Creer que una fuente confiable siempre basta.", "Se confunde confianza con suficiencia.", "Revisa si la fuente responde a tu pregunta."),
   ("No anotar las limitaciones.", "Se piensa que debilitan el trabajo.", "Declararlas muestra rigor.")],
  ([E("¿Una fuente confiable tiene autor identificable?", "Sí", "Es uno de los criterios."),
    E("¿Suficiente significa que alcanza para responder la pregunta?", "Sí", "Esa es su definición."),
    E("¿Una fuente que exagera y no cita datos merece cautela?", "Sí", "No se puede comprobar.")],
   [E("Fuente ficticia: artículo con autor, fecha de 2022 y ejemplos de poemas sobre el mar. ¿Es confiable?", "Sí", "Cumple los criterios."),
    E("Fuente ficticia: «Los poemas son bonitos». Pregunta: recursos de los poemas breves. ¿Es suficiente?", "No", "No trata el aspecto de la pregunta."),
    E("¿Qué conviene hacer si ninguna fuente alcanza: buscar más o responder igual?", "Buscar más", "Falta más información.")],
   [E("Fuente A: tiene autor, fecha y ejemplos citados. Fuente B: sin autor, sin fecha, con titulares exagerados. ¿Cuál usas como base?", "La fuente A", "Es más confiable."),
    E("Pregunta: ¿Qué rasgos tienen los personajes de las leyendas de una región? Fuente: un libro que describe cómo son los personajes de cinco leyendas de la región, con ejemplos. ¿Es suficiente para empezar?", "Sí, para empezar", "Trata el aspecto de la pregunta (los rasgos de los personajes) con ejemplos."),
    E("Dos fuentes confiables dicen cosas contradictorias. ¿Qué conviene: compararlas con criterios o elegir al azar?", "Compararlas con criterios", "Se justifica la decisión.")],
   [E("¿Por qué una fuente muy confiable puede no ser suficiente?", "Porque puede no tratar el aspecto de la pregunta", "La confianza y la suficiencia son criterios distintos."),
    E("¿Declarar limitaciones debilita o fortalece una investigación?", "La fortalece", "Muestra mucho rigor.")],
   [E("Una tabla de ejemplo muestra: Fuente A, autor sí, fecha sí, datos sí; Fuente B, autor no, fecha sí, datos no; Fuente C, autor sí, fecha no, datos sí. ¿Cuántos criterios cumple la fuente B de los tres?", "1", "Solo cumple fecha."),
    E("¿Cuál limitación es realista: «Las fuentes cubren solo poemas del siglo XX» o «Todo está perfecto»?", "Las fuentes cubren solo poemas del siglo XX", "Declara lo que no se cubre.")]),
  [E("Para tu pregunta sobre cuentos de misterio, encuentras un blog sin autor que dice «los cuentos de misterio son lo mejor». ¿Es confiable y suficiente?", "No es confiable ni suficiente", "No tiene autoría ni trata recursos.")],
  [E("¿Confiable y suficiente son lo mismo?", "No", "Un criterio es de confianza y otro de alcance."),
   E("¿Conviene hacer una tabla con criterios para comparar fuentes?", "Sí", "Ordena la evaluación."),
   E("¿Se deben anotar las limitaciones?", "Sí", "Muestra una transparencia necesaria.")],
  ("Evalúa estas tres fuentes ficticias para la pregunta «¿Qué recursos usan los poemas breves sobre el mar?»: A) un libro de análisis literario con autor, fecha 2018 y ejemplos citados de cinco poemas; B) un blog sin autor, sin fecha, que dice que los poemas del mar son los mejores; C) un artículo con autora y fecha 2022 que analiza la música de la lengua, sin mencionar el mar. Haz una tabla con los criterios autor, fecha, datos citados, relación con la pregunta y suficiencia, y concluye cuáles usarías y qué limitación declararías.",
   "A: autor sí, fecha sí, datos sí, relación sí, suficiente sí. B: autor no, fecha no, datos no, relación parcial, no suficiente. C: autor sí, fecha sí, datos sí, relación parcial (no habla del mar), suficiencia parcial. Usaría A como base y C como apoyo para recursos del sonido. Limitación: solo un libro analiza ejemplos de poemas del mar.",
   ["aplica los criterios", "distingue confiable de suficiente", "declara una limitación"], ["tabla", "conclusión", "limitación"], ["confundir confiable con suficiente", "no declarar limitaciones"], "Compara tu tabla con la de otra persona y revisen las diferencias."),
  "Evalúa una página de internet que hayas visitado con los tres criterios de confiabilidad.",
  "Haz una tabla de cinco criterios para comparar dos fuentes que tengas en casa.")

L(OA25, 4,
  MAT25,
  "Aprenderé a descartar con criterio las fuentes que no aportan a mi investigación porque se alejan del tema.",
  ["Evalúo confiabilidad y suficiencia.", "Conozco mi pregunta de investigación."],
  ["Descartar es una decisión de investigación, no una pérdida de tiempo. Una fuente se descarta por tres razones principales: 1) se aleja del tema (no trata tu aspecto), 2) no es confiable (sin autoría ni respaldo) o 3) repite lo que ya tienes sin aportar algo nuevo. Descartar bien te permite concentrarte en lo que ayuda.",
   "Para decidir rápido, revisa título, resumen, índice y palabras clave. Pregunta: ¿esta fuente trata mi aspecto?, ¿en el lugar o el tiempo que elegí?, ¿con ejemplos? Si no, descártala, aunque sea interesante. Anota por qué la descartaste («trata de poemas largos, y mi pregunta es sobre poemas breves») para no volver a evaluarla.",
   "Cuidado con dos errores. Uno es descartar demasiado pronto una fuente que parece lejana pero aporta una idea clave (por ejemplo, un glosario que define términos). El otro es guardar todo por miedo a perder algo, y terminar sin tiempo para leer lo importante. Un criterio claro evita ambos: la fuente se queda si ayuda a responder la pregunta; si no, se descarta con un motivo escrito."],
  [("descartar", "dejar de lado una fuente porque no aporta"), ("se aleja del tema", "no trata el aspecto de la pregunta"), ("redundante", "que repite lo que ya se tiene"), ("motivo", "razón que justifica una decisión")],
  [("Descartar por tema", "Pregunta: ¿Qué recursos usan los poemas breves sobre el mar? Fuente ficticia: «Historia del teatro en el siglo XX». ¿La descartas?",
    ["El título habla de teatro.", "No trata poemas ni el mar.", "La descarto."],
    "Sí, se aleja del tema"),
   ("Anotar el motivo", "Descartas un libro que trata de poemas largos. ¿Qué motivo anotas?",
    ["Mi pregunta es sobre poemas breves.", "El libro se centra en poemas largos.", "Anoto el motivo."],
    "Trata poemas largos y mi pregunta es sobre poemas breves")],
  [("Guardar todo por miedo a perder información.", "No se prioriza.", "Descarta lo que no responde a la pregunta."),
   ("Descartar sin anotar el motivo.", "Se olvida por qué.", "Escribe una razón breve.")],
  ([E("¿Se descarta una fuente que se aleja del tema?", "Sí", "No ayuda a responder."),
    E("¿Qué es una fuente redundante: la que repite lo que ya tienes o la que nunca te sirve?", "La que repite lo que ya tienes", "No aporta algo nuevo."),
    E("¿Conviene anotar el motivo del descarte?", "Sí", "Evita volver a evaluarla.")],
   [E("Pregunta: poemas breves sobre el mar. Fuente: «Historia del teatro en el siglo XX». ¿Se descarta?", "Sí", "No trata poemas ni el mar."),
    E("Pregunta: leyendas de una región. Fuente: «Recetas de cocina regional». ¿Se descarta?", "Sí", "Se aleja del tema."),
    E("¿Cuál es una razón válida para descartar: «es aburrida» o «no trata mi aspecto»?", "No trata mi aspecto", "Es un criterio de la investigación.")],
   [E("Pregunta: recursos de los poemas breves sobre el mar. Fuente 1: antología de poemas breves del mar con análisis. Fuente 2: manual de pesca. Fuente 3: artículo sobre recursos de poemas breves. ¿Cuántas descartas?", "1", "Solo el manual de pesca se aleja."),
    E("Ya tienes un artículo que enumera los recursos de los poemas breves. Una segunda fuente repite exactamente lo mismo. ¿La conservas como principal o la descartas como redundante?", "La descartas como redundante", "No aporta algo nuevo."),
    E("Fuente de ejemplo: glosario que define «metáfora» y «rima». Tu pregunta es sobre recursos. ¿La descartas?", "No", "Aporta definiciones útiles.")],
   [E("¿Qué error se comete al descartar una fuente lejana que define un término clave?", "Perder una idea clave", "Una fuente puede aportar aunque parezca lejana."),
    E("¿Qué error se comete al guardar todo por miedo?", "No tener tiempo para leer lo importante", "La sobrecarga impide profundizar.")],
   [E("Lista de ejemplo: 6 fuentes iniciales; 2 se alejan del tema; 1 es redundante; 1 no es confiable. ¿Cuántas quedan?", "2", "6 − 2 − 1 − 1 = 2."),
    E("Escribe un motivo bien redactado para descartar «Cuentos policiales largos» si tu pregunta es sobre cuentos breves.", "Trata cuentos largos y mi pregunta es sobre cuentos breves", "Relaciona la fuente con la pregunta.")]),
  [E("Tu pregunta trata de refranes sobre el trabajo en Chile. Tienes cuatro fuentes: una colección de refranes chilenos, un libro sobre refranes de otro continente, un artículo sobre refranes y trabajo en Chile y un cuento largo. ¿Cuántas fuentes descartarías por alejarse del tema?", "2", "Descartarías el libro de otro continente y el cuento largo.")],
  [E("¿Descartar bien ayuda a concentrarse?", "Sí", "Se trabaja con lo que aporta."),
   E("¿Se descarta una fuente por «es aburrida»?", "No", "No es un criterio de investigación."),
   E("¿Conviene anotar el motivo?", "Sí", "Fija el criterio.")],
  ("Pregunta de ejemplo: «¿Qué rasgos tienen los personajes de las leyendas de una región de Chile?». Fuentes ficticias: 1) «Leyendas de la región, recopilación con notas» (con autoría y fecha); 2) «Cómo hacer pan casero»; 3) «Mitos de otro continente»; 4) «Análisis de personajes en las leyendas de la región» (artículo con autoría); 5) «Leyendas de la región, copia sin autoría ni fecha»; 6) Glosario de términos literarios. Decide cuáles conservas y cuáles descartas y escribe el motivo de cada descarte.",
   "Conservo 1 (recopilación), 4 (análisis) y 6 (glosario, si hay términos nuevos). Descarto 2 (se aleja del tema), 3 (trata otro lugar) y 5 (no es confiable y repite la fuente 1).",
   ["decide con criterio", "anota motivos", "conserva lo que aporta"], ["lista de conservadas y descartadas con motivo"], ["descartar sin motivo", "guardar todo"], "Compara con otra persona y revisen si algún descarte se puede discutir."),
  "Revisa tres fuentes que tengas en casa para un tema y decide cuáles descartar.",
  "Escribe tres motivos de descarte bien redactados para tres fuentes imaginarias.")

L(OA25, 5,
  MAT25,
  "Aprenderé a organizar en categorías la información encontrada y a registrar los datos bibliográficos de las fuentes consultadas.",
  ["Selecciono fuentes y descarto las que no aportan.", "Sé tomar notas."],
  ["Organizar es agrupar la información en categorías: grupos de ideas con un rasgo común. Para la pregunta «¿Qué recursos usan los poemas breves sobre el mar?», las categorías podrían ser «recursos del sonido» (rima, repetición), «recursos de imagen» (metáfora, comparación) y «recursos de estructura» (verso corto, estrofa breve). Cada nota se guarda bajo la categoría que corresponde.",
   "Un método sencillo: 1) escribe cada hallazgo en una tarjeta o línea con la fuente de origen; 2) agrupa los hallazgos parecidos; 3) ponle nombre a cada grupo; 4) revisa que no haya categorías mezcladas; 5) detecta vacíos (categorías con poca información) y busca más datos si hace falta.",
   "Registrar las fuentes es indispensable. Una ficha bibliográfica sencilla incluye: apellido y nombre del autor, año de publicación, título, editorial o sitio y, si es un sitio web, la fecha de consulta. Ejemplo ficticio: Araya, Paula (2019). Poemas del mar. Editorial Ejemplo. Las fuentes se ordenan alfabéticamente por apellido. Así otras personas pueden verificar tus datos y tú demuestras honestidad."],
  [("categoría", "grupo de ideas que comparten un rasgo"), ("hallazgo", "dato o idea encontrada en una fuente"), ("ficha bibliográfica", "registro con los datos de una fuente"), ("orden alfabético", "orden según el abecedario")],
  [("Clasificar hallazgos", "Hallazgos de ejemplo: «rima», «metáfora», «verso corto». Categorías: sonido, imagen, estructura. Clasifica «metáfora».",
    ["La metáfora crea una imagen.", "Pertenece a la categoría de imagen.", "Anoto: imagen."],
    "Imagen"),
   ("Ordenar referencias", "Ordena alfabéticamente por apellido: Soto, Araya, Muñoz.",
    ["Miro la primera letra.", "A, M, S.", "El orden es Araya, Muñoz, Soto."],
    "Araya, Muñoz, Soto")],
  [("No registrar las fuentes.", "Se piensa que se recordarán.", "Anota autor, año, título y sitio."),
   ("Mezclar categorías.", "Se agrupa sin criterio claro.", "Cada categoría debe tener un rasgo común.")],
  ([E("¿Una categoría es un grupo de ideas con un rasgo común?", "Sí", "Es la definición."),
    E("¿Una ficha bibliográfica incluye autor y año?", "Sí", "Son datos básicos."),
    E("¿Las referencias se ordenan por apellido?", "Sí", "Se ordenan alfabéticamente.")],
   [E("Categorías: sonido, imagen, estructura. ¿Dónde clasificas «rima»?", "Sonido", "La rima es un recurso sonoro."),
    E("Categorías: sonido, imagen, estructura. ¿Dónde clasificas «verso corto»?", "Estructura", "Se refiere a la forma del poema."),
    E("Categorías: sonido, imagen, estructura. ¿Dónde clasificas «comparación»?", "Imagen", "Relaciona dos cosas para crear una imagen.")],
   [E("Ordena alfabéticamente por apellido: Soto, Araya, Muñoz. ¿Cuál va primero?", "Araya", "La A va antes que la M y la S."),
    E("Ordena alfabéticamente: Pérez, González, Díaz. ¿Cuál va último?", "Pérez", "Orden: Díaz, González, Pérez."),
    E("Ficha ficticia: «Araya, Paula (2019). Poemas del mar. Editorial Ejemplo». ¿Cuál es el año?", "2019", "Está entre paréntesis.")],
   [E("Un grupo de notas mezcla «rima», «metáfora» y «verso corto» bajo el título «Recursos». ¿Por qué conviene dividirlo?", "Porque mezclan rasgos de sonido, imagen y estructura", "Las categorías deben ser más precisas."),
    E("Una categoría tiene solo una nota. ¿Qué conviene: buscar más datos o ignorarla?", "Buscar más datos", "Hay un vacío.")],
   [E("Ficha de ejemplo: ¿cuál elemento falta en «Araya, Paula. Poemas del mar. Editorial Ejemplo»?", "El año", "Falta la fecha de publicación."),
    E("Lista de ejemplo de hallazgos: rima, repetición, ritmo, metáfora, comparación. Si sonido tiene tres, ¿cuántos son de imagen?", "2", "Metáfora y comparación son de imagen; rima, repetición y ritmo son de sonido.")]),
  [E("Una estudiante registra una fuente web: «Díaz, Laura (2020). Recursos poéticos. Sitio Ejemplo». Falta un dato propio de las fuentes en línea. ¿Cuál es?", "La fecha de consulta", "Las páginas web cambian, por eso se anota cuándo se consultaron.")],
  [E("¿Las fuentes se registran para poder verificarlas?", "Sí", "Dan una transparencia necesaria."),
   E("¿Un vacío es una categoría con poca información?", "Sí", "Indica que falta buscar."),
   E("¿Las categorías deben tener un rasgo común?", "Sí", "Para no mezclar ideas.")],
  ("Con estos hallazgos de ejemplo sobre «¿Qué recursos usan los poemas breves sobre el mar?»: rima (Fuente A), metáfora (Fuente A), verso corto (Fuente B), repetición (Fuente C), comparación (Fuente B), estrofa de dos versos (Fuente C). Fuentes ficticias: A) Araya, Paula (2019). Poemas del mar. Editorial Ejemplo. B) Muñoz, Carlos (2021). Versos breves. Editorial Muestra. C) Díaz, Laura (2020). Recursos poéticos. Sitio Ejemplo (consultado en 2024). 1) Crea tres categorías y clasifica los hallazgos. 2) Detecta si hay algún vacío. 3) Ordena las referencias alfabéticamente.",
   "Sonido: rima (A), repetición (C). Imagen: metáfora (A), comparación (B). Estructura: verso corto (B), estrofa de dos versos (C). No hay vacíos (cada categoría tiene dos hallazgos). Referencias en orden: Araya (2019); Díaz (2020); Muñoz (2021).",
   ["crea categorías claras", "detecta vacíos", "ordena y registra fuentes"], ["tabla de categorías", "referencias ordenadas"], ["mezclar categorías", "omitir el año o el autor"], "Revisa con otra persona si las categorías son claras."),
  "Crea la ficha bibliográfica de un libro de tu casa con autor, año y título.",
  "Clasifica diez ideas sobre un mismo tema en tres categorías con nombre propio.")

L(OA25, 6,
  MAT25,
  "Aprenderé a elaborar un texto oral o escrito bien estructurado que comunique los hallazgos de mi investigación, incluyendo sus límites.",
  ["Organizo los hallazgos en categorías.", "Registro las fuentes consultadas."],
  ["Un informe de investigación comunica lo que se descubrió. Su estructura incluye: 1) introducción (tema, pregunta y alcance); 2) desarrollo (hallazgos por categoría, con ejemplos y fuentes); 3) conclusión (respuesta a la pregunta); 4) límites (qué no se pudo cubrir); 5) referencias (fuentes consultadas). Puede presentarse por escrito o como exposición oral.",
   "Al redactar, usa tus categorías como párrafos o secciones. Cada hallazgo se apoya en una fuente: «Según Araya (2019), la rima da musicalidad». Evita copiar frases completas: parafrasea y cita. La conclusión responde con claridad a la pregunta inicial. Los límites se declaran con honestidad: «Esta investigación solo revisó cuatro poemas, por lo que no puede afirmar que todos los poemas breves usen los mismos recursos».",
   "Cuida la coherencia: la conclusión debe corresponder a los hallazgos y no ir más allá. Un error frecuente es generalizar (decir «todos...» tras revisar pocos casos). Usa conectores para hilar las ideas y un registro adecuado. Si lo presentas oralmente, apoya con material visual y prepara recapitulaciones. Termina siempre mencionando las fuentes."],
  [("hallazgo", "dato o idea encontrada en una fuente"), ("conclusión", "respuesta a la pregunta basada en los hallazgos"), ("límite", "aspecto que la investigación no pudo cubrir"), ("parafrasear", "decir con tus palabras lo que dice una fuente")],
  [("Declarar un límite", "Revisaste cuatro poemas breves. ¿Cuál es un límite honesto?",
    ["Solo se revisaron cuatro poemas.", "No se puede generalizar a todos.", "Lo declaro."],
    "Solo se revisaron cuatro poemas, por lo que no se puede afirmar que todos usen los mismos recursos"),
   ("Citar una fuente", "Usa la fuente ficticia «Araya (2019)» para decir que la rima da musicalidad.",
    ["Parafraseo la idea.", "Cito el apellido y el año.", "Escribo: Según Araya (2019), la rima da musicalidad."],
    "Según Araya (2019), la rima da musicalidad.")],
  [("Generalizar a partir de pocos casos.", "Se quiere una conclusión fuerte.", "Declara los límites y ajusta la conclusión."),
   ("Copiar frases completas de la fuente.", "Se evita parafrasear.", "Parafrasea y cita.")],
  ([E("¿Cuál es la primera parte de un informe: introducción o referencias?", "Introducción", "Presenta tema y pregunta."),
    E("¿La conclusión responde a la pregunta inicial?", "Sí", "Es su función."),
    E("¿Parafrasear es decir con tus palabras lo que dice una fuente?", "Sí", "Esa es la definición.")],
   [E("¿Cuál es una buena cita: «Según Araya (2019), la rima da musicalidad» o «La rima da musicalidad»?", "Según Araya (2019), la rima da musicalidad", "Indica la fuente."),
    E("¿Dónde van las fuentes consultadas: al comienzo o en las referencias finales?", "En las referencias finales", "Cierran el informe."),
    E("¿Qué parte declara lo que no se pudo cubrir: los límites o la introducción?", "Los límites", "Es su función.")],
   [E("Revisaste cuatro poemas. ¿Cuál conclusión es adecuada: «Estos cuatro poemas usan rima y metáfora» o «Todos los poemas del mundo usan rima y metáfora»?", "Estos cuatro poemas usan rima y metáfora", "No generaliza más allá de los casos."),
    E("Ordena las partes de un informe: conclusión, introducción, desarrollo. ¿Cuál va en el medio?", "Desarrollo", "Orden: introducción, desarrollo, conclusión."),
    E("¿Qué sección declara honestamente: «Solo revisé cuatro poemas»?", "Los límites", "Dice lo que no se pudo cubrir.")],
   [E("Un estudiante copia tres párrafos de una fuente sin citarla. ¿Qué problema tiene?", "No parafrasea ni cita la fuente", "Es una falta de honestidad."),
    E("¿Por qué la conclusión debe corresponder a los hallazgos?", "Para no afirmar más de lo que se encontró", "Mantiene la coherencia.")],
   [E("En una exposición de ejemplo, ¿qué conviene al final: mencionar las fuentes o terminar sin nada?", "Mencionar las fuentes", "Da más credibilidad."),
    E("Evalúa: «Todos los poemas son metafóricos porque revisé uno». ¿Qué error tiene?", "Generaliza desde un solo caso", "Es una conclusión sin respaldo suficiente.")]),
  [E("Un informe de ejemplo concluye: «Los cuatro poemas revisados usan repetición». Los límites dicen: «No se revisaron poemas de otras regiones». ¿Es coherente?", "Sí", "La conclusión se limita a lo revisado y los límites lo reconocen.")],
  [E("¿Un informe tiene introducción, desarrollo, conclusión, límites y referencias?", "Sí", "Esas son sus partes."),
   E("¿Se deben citar las fuentes en el texto?", "Sí", "Dan respaldo a cada hallazgo."),
   E("¿Se debe generalizar tras revisar pocos casos?", "No", "Se declaran los límites.")],
  ("Con la información de ejemplo de la clase anterior (rima y repetición en la categoría sonido; metáfora y comparación en imagen; verso corto y estrofa de dos versos en estructura; fuentes: Araya 2019, Muñoz 2021, Díaz 2020), escribe un informe breve de seis a ocho líneas que incluya: introducción con la pregunta, una oración por categoría con cita, una conclusión que responda y una frase de límites.",
   "Ejemplo: «Esta investigación respondió ¿qué recursos usan los poemas breves sobre el mar? Según Araya (2019) y Díaz (2020), los poemas usan rima y repetición para crear sonido. Según Araya (2019) y Muñoz (2021), usan metáfora y comparación para crear imágenes. Según Muñoz (2021) y Díaz (2020), son breves, con versos cortos y estrofas de dos versos. En conclusión, usan sonido, imagen y estructura breve. Límite: se revisaron solo tres fuentes y no se analizaron poemas de otras regiones».",
   ["usa las cuatro partes", "cita las fuentes", "declara límites"], ["informe de seis a ocho líneas"], ["generalizar", "copiar sin citar"], "Lee tu informe a otra persona y pídele que diga qué respuesta dio a la pregunta."),
  "Escribe una conclusión de dos líneas para una pregunta que hayas investigado.",
  "Prepara una exposición de dos minutos con tu informe y ensaya con una persona de tu casa.")
